'use client';
import React from 'react';

import { Categories, SkinTonePickerLocation } from 'emoji-picker-react/primitives';
import * as Picker from 'emoji-picker-react/primitives';


// In context: a "Set a status" dialog. The picker is an inline part of
// the form — search and grid only, with status-friendly suggestions first
// (suggestedEmojis) and the category renamed through `categories`.
export type ShellProps = {
  /** The picker root: Picker.Root, or a styled() wrapper of it. */
  Root?: React.ElementType;
  className?: string;
};

export function Shell({ Root: RootComponent = Picker.Root, className }: ShellProps) {
  return (
    <div className="status-backdrop">
      <div className="status-dialog" role="dialog" aria-labelledby="status-title">
        <h2 id="status-title" className="status-title">
          Set a status
        </h2>
        <div className="status-field">
          <span className="status-current" aria-hidden>
            🌴
          </span>
          <span className="status-text">On vacation until Monday</span>
        </div>
        <RootComponent
          className={className}
          searchPlaceholder="Search for an emoji"
          skinTonePickerLocation={SkinTonePickerLocation.NONE}
          autoFocusSearch={false}
          suggestedEmojis={['1f334', '1f912', '1f3e0', '1f4c5', '1f68c', '1f3a7', '1f37d-fe0f', '1f319']}
          categories={[
            { category: Categories.SUGGESTED, name: 'For your status' },
            Categories.SMILEYS_PEOPLE,
            Categories.TRAVEL_PLACES,
            Categories.ACTIVITIES,
            Categories.OBJECTS,
          ]}
        >
          <Picker.Search />
          <Picker.Viewport>
            <Picker.List />
            <Picker.Empty />
          </Picker.Viewport>
        </RootComponent>
        <div className="status-row">
          <span>Clear after</span>
          <span className="status-select">Today ▾</span>
        </div>
        <div className="status-actions">
          <button type="button">Cancel</button>
          <button type="button" className="status-save">
            Save
          </button>
        </div>
      </div>
    </div>
  );
}

/* The host app around the picker (shared by every stack variant). */
.status-backdrop {
  display: grid;
  place-items: center;
  width: 560px;
  height: 600px;
  background: rgb(15 23 42 / 55%);
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
.status-dialog {
  width: 440px;
  padding: 22px;
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 24px 60px rgb(15 23 42 / 35%);
  color: #0f172a;
}
.status-title {
  margin: 0 0 14px;
  font-size: 18px;
}
.status-field {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border: 1px solid #cbd5e1;
  border-radius: 10px;
}
.status-current {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 8px;
  background: #f1f5f9;
  font-size: 20px;
}
.status-row {
  display: flex;
  justify-content: space-between;
  margin-top: 14px;
  color: #334155;
  font-size: 14px;
}
.status-select {
  font-weight: 600;
}
.status-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 18px;
}
.status-actions button {
  height: 36px;
  padding: 0 16px;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  background: #ffffff;
  color: #0f172a;
  font: inherit;
  font-weight: 600;
}
.status-actions .status-save {
  border-color: #0f172a;
  background: #0f172a;
  color: #ffffff;
}

/* Set a status — the picker as an inline form section: no tabs, no
   preview, a bordered well under the status field. */
.status-picker {
  --epr-bg-color: #f8fafc;
  --epr-text-color: #475569;
  --epr-highlight-color: #0f172a;
  --epr-hover-bg-color: #e2e8f0;
  --epr-focus-bg-color: #cbd5e1;
  --epr-search-input-bg-color: #ffffff;
  --epr-search-input-bg-color-active: #ffffff;
  --epr-search-border-color: #cbd5e1;
  --epr-search-border-color-active: #0f172a;
  --epr-search-input-height: 34px;
  --epr-search-input-border-radius: 8px;
  --epr-search-input-text-color: #0f172a;
  --epr-search-input-placeholder-color: #64748b;
  --epr-category-label-bg-color: #f8fafcf2;
  --epr-category-label-text-color: #475569;
  --epr-category-label-height: 28px;
  --epr-emoji-size: 24px;
  --epr-emoji-padding: 5px;
  --epr-horizontal-padding: 10px;
  height: 250px;
  margin-top: 12px;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  background: var(--epr-bg-color);
}
.status-picker [data-epr-part='search'] > * {
  padding: 10px 10px 4px;
}
.status-picker [data-epr-part='category-label'] {
  font-size: 12px;
  font-weight: 600;
  text-transform: none;
}
.status-picker [data-epr-part='emoji'] {
  border-radius: 6px;
}

